double ft = 0.3048;
double tx = Tama.Args.Get(args, "x", 0.15) / ft;
double ty = Tama.Args.Get(args, "y", 0.1505) / ft;
double tz = Tama.Args.Get(args, "z", 0.3) / ft;
double tol = Tama.Args.Get(args, "tolMm", 1.0) / 304.8;

Func<List<double[]>> snapLocs = () => {
    var l = new List<double[]>();
    foreach (ProjectLocation pl in doc.ProjectLocations) {
        var pp = pl.GetProjectPosition(XYZ.Zero);
        l.Add(new[]{pp.EastWest, pp.NorthSouth, pp.Elevation, pp.Angle});
    }
    return l;
};
var bps = new FilteredElementCollector(doc).OfClass(typeof(BasePoint)).Cast<BasePoint>().ToList();
var sp = bps.First(b => b.IsShared);
var pbp = bps.First(b => !b.IsShared);

var status = WorksharingUtils.GetCheckoutStatus(doc, sp.Id);
if (status == CheckoutStatus.OwnedByOtherUser) throw new Exception("Survey point is owned by another user.");

var locsBefore = snapLocs();
var pbpBefore = pbp.SharedPosition;
var spBeforeInt = sp.Position; var spBeforeShared = sp.SharedPosition;
bool clippedBefore = sp.Clipped;
bool pinnedBefore = sp.Pinned;

if (sp.Pinned) sp.Pinned = false;
sp.Clipped = false;
doc.Regenerate();
var delta = new XYZ(tx, ty, tz) - sp.Position;
ElementTransformUtils.MoveElement(doc, sp.Id, delta);
doc.Regenerate();
sp.Clipped = clippedBefore;
sp.Pinned = pinnedBefore;
doc.Regenerate();

var locsAfter = snapLocs();
for (int i = 0; i < locsBefore.Count; i++)
  for (int k = 0; k < 3; k++)
    if (Math.Abs(locsBefore[i][k] - locsAfter[i][k]) > tol || Math.Abs(locsBefore[i][3] - locsAfter[i][3]) > 1e-7)
      throw new Exception("Project location values changed - rolled back.");
if (pbp.SharedPosition.DistanceTo(pbpBefore) > tol) throw new Exception("Project base point shared value changed - rolled back.");
if (sp.Position.DistanceTo(new XYZ(tx, ty, tz)) > tol) throw new Exception("Survey point did not reach target - rolled back. Now at " + sp.Position.Multiply(ft));

Func<XYZ, double[]> m = p => new[]{Math.Round(p.X*ft,4), Math.Round(p.Y*ft,4), Math.Round(p.Z*ft,4)};
return new {
  surveyBefore = new { internal_m = m(spBeforeInt), shared_m = m(spBeforeShared) },
  surveyAfter = new { internal_m = m(sp.Position), shared_m = m(sp.SharedPosition), clipped = sp.Clipped, pinned = sp.Pinned },
  pbpShared_m = m(pbp.SharedPosition),
  locationsUnchanged = true
};
